package com.wizzadrds.theworldremembers.rumor; import com.mojang.serialization.Codec; import com.mojang.serialization.codecs.RecordCodecBuilder; import net.minecraft.core.UUIDUtil; import java.util.*; public record Conversation(UUID first,UUID second,long tick,List<KnowledgeFact> facts){public static final Codec<Conversation> CODEC=RecordCodecBuilder.create(i->i.group(UUIDUtil.CODEC.fieldOf("first").forGetter(Conversation::first),UUIDUtil.CODEC.fieldOf("second").forGetter(Conversation::second),Codec.LONG.fieldOf("tick").forGetter(Conversation::tick),KnowledgeFact.CODEC.listOf().fieldOf("facts").forGetter(Conversation::facts)).apply(i,Conversation::new));}
